/**
 * Colour — every value comes from tokens.json (lifted from Foundation by
 * tools/tokens/extract.mjs) or board-only.json (a board draws it, Foundation does
 * not). This file and its two JSON sources are the ONLY place a colour literal may
 * exist; `npm run gate:tokens` fails the build anywhere else.
 */

import tokens from './tokens.json'
import boardOnly from './board-only.json'
// The client's Resident App design at its EXACT values (M42 §2.1), generated by tools/design/resident-tokens.mjs:
// rd-<the design's own name>. Five of Foundation's names ship darker than these (D-M081, D-M155, D-M174); the
// Resident App's token module (apps/resident/src/design/tokens.ts) draws with these, and nothing else does.
import residentDesign from './resident-design.json'

type FoundationToken = keyof typeof tokens.colors
type SemanticToken = keyof typeof tokens.semantic
type BoardOnlyToken = keyof typeof boardOnly.colors
type ResidentDesignToken = keyof typeof residentDesign.colors

export type ColorToken = FoundationToken | SemanticToken | BoardOnlyToken | ResidentDesignToken

const boardOnlyHex = Object.fromEntries(
  Object.entries(boardOnly.colors).map(([name, entry]) => [name, entry.hex]),
) as Record<BoardOnlyToken, string>

/** Flat map, token name → hex. `palette['navy-600']`. */
export const palette: Readonly<Record<ColorToken, string>> = Object.freeze({
  ...tokens.colors,
  ...tokens.semantic,
  ...boardOnlyHex,
  ...residentDesign.colors,
})

export const color = (token: ColorToken): string => palette[token]

/**
 * A token at an opacity — the boards use translucent whites and ambers for
 * overlays (`rgba(255,255,255,.14)`, `rgba(255,182,39,.1)`). Built here so no
 * component ever writes an rgba() literal.
 */
export function alpha(token: ColorToken, opacity: number): string {
  const hex = palette[token].replace('#', '')
  const full = hex.length === 3 ? hex.split('').map((c) => c + c).join('') : hex
  const r = parseInt(full.slice(0, 2), 16)
  const g = parseInt(full.slice(2, 4), 16)
  const b = parseInt(full.slice(4, 6), 16)
  return `rgba(${r},${g},${b},${opacity})`
}

export const transparent = 'transparent'
